#include "umicom/teacher/curriculum_graph.h"
int main(void) { UmiTeacherCurriculumGraph g; uint8_t done[3]={1U,0U,0U}; umi_teacher_curriculum_graph_init(&g,3U); if(umi_teacher_curriculum_graph_add(&g,0U,1U)!=UMI_STATUS_OK) return 1; if(umi_teacher_curriculum_graph_add(&g,1U,2U)!=UMI_STATUS_OK) return 2; if(umi_teacher_curriculum_graph_has_cycle(&g)) return 3; if(!umi_teacher_curriculum_graph_prerequisite_satisfied(&g,1U,done,3U)) return 4; if(umi_teacher_curriculum_graph_add(&g,2U,0U)!=UMI_STATUS_OK) return 5; if(!umi_teacher_curriculum_graph_has_cycle(&g)) return 6; return 0; }
